function tileSide(planks) {
  for (let side = Math.min(...planks); side >= 1; side--) {
    if (planks.every((p) => p % side === 0)) return side;
  }
  return 1;
}

function tileSide(planks) {
  const gcd = (a, b) => {
    while (b !== 0) [a, b] = [b, a % b];
    return a;
  };
  let g = planks[0];
  for (let i = 1; i < planks.length; i++) g = gcd(g, planks[i]);
  return g;
}
